static class Launcher {
 public static string Assets;
 [DllImport("kernel32",SetLastError=true,CharSet=CharSet.Unicode)] static extern bool SetDllDirectory(string path);
 [STAThread] static void Main(string[] args){
  Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);
  try{
   Assets=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"LibroStudio","Maquetario-3.24.0");
   Directory.CreateDirectory(Assets);
   using(var zip=new ZipArchive(Assembly.GetExecutingAssembly().GetManifestResourceStream("bundle.zip"),ZipArchiveMode.Read))foreach(var entry in zip.Entries){string path=Path.GetFullPath(Path.Combine(Assets,entry.FullName));if(!path.StartsWith(Assets+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new Exception("Paquete inválido");if(entry.Name.Length==0){Directory.CreateDirectory(path);continue;}Directory.CreateDirectory(Path.GetDirectoryName(path));using(var src=entry.Open())using(var dst=File.Create(path))src.CopyTo(dst);}
   SetDllDirectory(Assets);
   AppDomain.CurrentDomain.AssemblyResolve+=delegate(object s,ResolveEventArgs e){string path=Path.Combine(Assets,new AssemblyName(e.Name).Name+".dll");return File.Exists(path)?Assembly.Load(File.ReadAllBytes(path)):null;};
   Run(args);
  }catch(Exception ex){ThemedNotice.Show(null,"Maquetario no pudo iniciar",ex.Message);}
 }
 [System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]
 static void Run(string[] args){Application.Run(new Desktop(args));}
}
