 async void Message(object sender,CoreWebView2WebMessageReceivedEventArgs e){if(e.Source!="https://librostudio.local/index.html")return;string id="";try{var data=json.Deserialize<Dictionary<string,object>>(e.WebMessageAsJson);id=Convert.ToString(data["id"]);string action=Convert.ToString(data["action"]);var p=data.ContainsKey("payload")?data["payload"] as Dictionary<string,object>:null;
 if(action=="ready"){Reply(id,new{fonts=FontFamily.Families.Select(f=>f.Name).ToArray(),native=true,selftest=args.Contains("--self-test")});}
 else if(action=="dirty"){dirty=Convert.ToBoolean(p["dirty"]);Text=Convert.ToString(p["title"])+(dirty?" *":"")+" · Maquetario";Reply(id,true);}
 else if(action=="locale"){language=Convert.ToString(p["language"]);Reply(id,true);}
 else if(action=="newProject"){projectPath=null;SetPackageFonts(null);Reply(id,true);}
 else if(action=="assistantStatus"){Reply(id,AssistantStatus());}
 else if(action=="assistantConfigure"){SaveAssistant(p);Reply(id,AssistantStatus());}
 else if(action=="assistantReview"){await AssistantReview(id,p);}
 else if(action=="packageProject"){if(busy)throw new Exception("Hay otra salida en curso.");busy=true;try{await PackageProject(id,p);}finally{busy=false;}}
 else if(action=="clipboardSvg"){Reply(id,ReadClipboardSvg());}
 else if(action=="appInfo"){Reply(id,GetAppInfo());}
 else if(action=="openRecent"){OpenRecent(id,Convert.ToString(p["path"]));}
 else if(action=="save"||action=="saveAs"){Reply(id,SaveProject(Convert.ToString(p["json"]),Convert.ToString(p["name"]),action=="saveAs"));}
 else if(action=="open"){using(var d=new OpenFileDialog{Filter="Proyectos Maquetario|*.mqt;*.maquetario;*.librostudio;*.json|Proyecto Maquetario (*.mqt)|*.mqt"}){if(d.ShowDialog(this)==DialogResult.OK){string content=File.ReadAllText(d.FileName);if(content.Length>80000000)throw new Exception("El proyecto supera 80 MB.");projectPath=d.FileName;SetPackageFonts(projectPath);RecordRecent(d.FileName,content);Reply(id,new{content=content,path=d.FileName,packageFaces=packageFaces});}else Reply(id,null);}}
 else if(action=="fontCatalog"||action=="refreshFonts"){await LoadFontCatalog(id,action=="refreshFonts");}
 else if(action=="fontGlyphs"){await GetFontGlyphs(id,Convert.ToString(p["fontId"]));}
 else if(action=="chooseFontFolder"){await ChooseFontFolder(id);}
 else if(action=="printers"){Reply(id,GetPrinters());}
 else if(action=="print"||action=="outputPdf"){if(busy)throw new Exception("Hay otra salida en curso.");busy=true;try{await OutputDocument(id,p,action=="print");}finally{busy=false;}}
 else if(action=="export"){if(busy)throw new Exception("Ya hay una exportación en curso.");busy=true;try{await Export(id,p);}finally{busy=false;}}
 else if(action=="savePdf"){using(var d=new SaveFileDialog{Filter="Documento PDF|*.pdf",FileName=Convert.ToString(p["name"])+".pdf"}){if(d.ShowDialog(this)==DialogResult.OK){File.WriteAllBytes(d.FileName,Convert.FromBase64String(Convert.ToString(p["base64"])));Reply(id,new{saved=true,path=d.FileName});}else Reply(id,new{saved=false});}}
 else if(action=="closeSaved"){if(!dirty){closingAllowed=true;Reply(id,true);Close();}else Reply(id,false);}
 else if(action=="closeDiscard"){if(closePromptShown){closingAllowed=true;Reply(id,true);Close();}else Reply(id,false);}
 else if(action=="closeCancelled"){closePromptShown=false;Reply(id,true);}
 }catch(Exception ex){Reply(id,null,ex.Message);}}
 string ReadClipboardSvg(){
  var data = Clipboard.GetDataObject();
  if(data == null) return null;
  foreach(string format in data.GetFormats(false)){
   if(format.IndexOf("svg",StringComparison.OrdinalIgnoreCase) < 0 && format != DataFormats.UnicodeText && format != DataFormats.Text) continue;
   object value = data.GetData(format,false);
   string text = value as string;
   var stream = value as MemoryStream;
   if(stream != null && stream.Length <= 16000000){
    byte[] bytes = stream.ToArray();
    text = System.Text.Encoding.UTF8.GetString(bytes);
    if(text.IndexOf('<') >= 0 && text.IndexOf('\0') >= 0) text = System.Text.Encoding.Unicode.GetString(bytes);
   }
   if(text != null && text.Length <= 16000000 && text.IndexOf("<svg",StringComparison.OrdinalIgnoreCase) >= 0) return text;
  }
  return null;
 }
 bool SaveProject(string content,string name,bool saveAs=false){string target=projectPath;if(saveAs||target==null||!string.Equals(Path.GetExtension(target),".mqt",StringComparison.OrdinalIgnoreCase)){using(var d=new SaveFileDialog{Filter="Proyecto Maquetario (*.mqt)|*.mqt",DefaultExt="mqt",AddExtension=true,FileName=saveAs&&target!=null?Path.GetFileNameWithoutExtension(target)+" - copia.mqt":target==null?CleanName(name)+".mqt":Path.ChangeExtension(target,".mqt")}){if(target!=null)d.InitialDirectory=Path.GetDirectoryName(target);if(d.ShowDialog(this)!=DialogResult.OK)return false;target=d.FileName;}}WriteProjectFile(target,content);projectPath=target;RecordRecent(target,content);dirty=false;return true;}
 static void WriteProjectFile(string target,string content){string temp=target+"."+Guid.NewGuid().ToString("N")+".tmp";try{File.WriteAllText(temp,content,System.Text.Encoding.UTF8);if(File.Exists(target))File.Replace(temp,target,null);else File.Move(temp,target);}finally{if(File.Exists(temp))File.Delete(temp);}}
 object CheckProjectSaving(){string a=Path.Combine(Path.GetTempPath(),"maquetario-save-"+Guid.NewGuid()+".mqt"),b=Path.Combine(Path.GetTempPath(),"maquetario-copy-"+Guid.NewGuid()+".mqt"),old=projectPath;bool oldDirty=dirty;try{WriteProjectFile(a,"original");projectPath=a;if(!SaveProject("updated","Prueba"))throw new Exception("Save existing");WriteProjectFile(b,"copy");if(File.ReadAllText(a)!="updated"||File.ReadAllText(b)!="copy")throw new Exception("Copy changed source");return new{ok=true,checks=new[]{"Guardar actualiza el archivo existente sin diálogo","Escritura de copia no modifica el original"}};}finally{projectPath=old;dirty=oldDirty;if(File.Exists(a))File.Delete(a);if(File.Exists(b))File.Delete(b);}}
 static string CleanName(string name){foreach(char c in Path.GetInvalidFileNameChars())name=name.Replace(c,'_');return name;}
 async Task Export(string id,Dictionary<string,object> p){string temp=Path.Combine(Path.GetTempPath(),"librostudio-"+Guid.NewGuid()+".pdf");try{await view.CoreWebView2.ExecuteScriptAsync("window.preparePrint()");await Task.Delay(350);var settings=view.CoreWebView2.Environment.CreatePrintSettings();settings.ShouldPrintBackgrounds=true;settings.ShouldPrintHeaderAndFooter=false;settings.MarginTop=settings.MarginBottom=settings.MarginLeft=settings.MarginRight=0;settings.PageWidth=Convert.ToDouble(p["width"])/25.4;settings.PageHeight=Convert.ToDouble(p["height"])/25.4;bool ok=await view.CoreWebView2.PrintToPdfAsync(temp,settings);if(!ok)throw new Exception("No se pudo generar el PDF.");Reply(id,new{base64=Convert.ToBase64String(File.ReadAllBytes(temp))});}finally{view.CoreWebView2.ExecuteScriptAsync("window.clearPrint()");if(File.Exists(temp))File.Delete(temp);}}
 void Reply(string id,object result,string error=null){view.CoreWebView2.PostWebMessageAsJson(json.Serialize(new{id=id,result=result,error=error}));}
 async void OnClosing(object sender,FormClosingEventArgs e){if(closingAllowed)return;if(busy||assistantWorking){e.Cancel=true;try{await view.CoreWebView2.ExecuteScriptAsync("window.showBusyCloseNotice()");}catch{}return;}if(!dirty)return;e.Cancel=true;if(closePromptShown)return;closePromptShown=true;try{string ready=await view.CoreWebView2.ExecuteScriptAsync("typeof window.requestCloseConfirmation==='function'?(window.requestCloseConfirmation(),true):false");if(ready!="true"){closePromptShown=false;ThemedNotice.Show(this,"Tu trabajo sigue abierto","No se pudo abrir el aviso. Guardá la publicación antes de cerrar.");}}catch{closePromptShown=false;ThemedNotice.Show(this,"Tu trabajo sigue abierto","Guardá la publicación antes de cerrar.");}}

}
